MINIMUM_FOR_DISCOUNT = 100000
DISCOUNT_RATE = 0.10


def apply_discount(subtotal):
    if subtotal > MINIMUM_FOR_DISCOUNT:
        return round(subtotal * (1 - DISCOUNT_RATE))
    return subtotal

import unittest

from discount import apply_discount


class ApplyDiscountTest(unittest.TestCase):
    def test_no_discount_below_minimum(self):
        self.assertEqual(50000, apply_discount(50000))

    def test_discount_at_minimum(self):
        self.assertEqual(90000, apply_discount(100000))

    def test_discount_above_minimum(self):
        self.assertEqual(180000, apply_discount(200000))
